import 'package:cloud_firestore/cloud_firestore.dart';
import 'package:firebase_auth/firebase_auth.dart';
import 'package:flutter/material.dart';
import 'chat_detail.dart';
import '../services/healthline_firestore_service.dart';

class MessagesScreen extends StatelessWidget {const MessagesScreen({super.key});static const bg=Color(0xFF101010),surface=Color(0xFF1C1A1A),mauve=Color(0xFFB78A9B),muted=Color(0xFFAAAAAA);
 @override Widget build(BuildContext context){final uid=FirebaseAuth.instance.currentUser?.uid;return Scaffold(backgroundColor:bg,appBar:AppBar(backgroundColor:bg,foregroundColor:Colors.white,title:const Text('Messages')),body:uid==null?const Center(child:Text('Please sign in to view messages.',style:TextStyle(color:muted))):StreamBuilder<QuerySnapshot<Map<String,dynamic>>>(stream:HealthLineFirestoreService.instance.db.collection('conversations').where('participantUids',arrayContains:uid).snapshots(),builder:(context,s){if(s.hasError)return Center(child:Text('Could not load messages: ${s.error}',style:const TextStyle(color:Colors.redAccent)));if(!s.hasData)return const Center(child:CircularProgressIndicator());final docs=s.data!.docs;if(docs.isEmpty)return const Center(child:Padding(padding:EdgeInsets.all(24),child:Text('Your conversations will appear here when you message a clinic or a patient.',textAlign:TextAlign.center,style:TextStyle(color:muted))));return ListView.separated(padding:const EdgeInsets.all(16),itemCount:docs.length,separatorBuilder:(_,__)=>const SizedBox(height:8),itemBuilder:(context,i){final d=docs[i].data();final ids=List<String>.from(d['participantUids']??const []);final other=ids.firstWhere((id)=>id!=uid,orElse:()=>uid);return FutureBuilder<DocumentSnapshot<Map<String,dynamic>>>(future:HealthLineFirestoreService.instance.db.collection('users').doc(other).get(),builder:(context,u){final name=(u.data?.data()?['displayName']??'Patient / Clinic').toString();return Card(color:surface,child:ListTile(leading:const CircleAvatar(backgroundColor:Color(0xFF423636),child:Icon(Icons.chat_bubble_outline,color:mauve)),title:Text(name,style:const TextStyle(color:Colors.white)),subtitle:Text((d['lastMessage']??'No messages yet').toString(),maxLines:1,overflow:TextOverflow.ellipsis,style:const TextStyle(color:muted)),onTap:()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>ChatDetailScreen(hospital:name,otherUid:other,conversationId:docs[i].id))));});});}));}
}
